const s = $input.first().json;
const cfg = $('Setup Daily').first().json.CONFIG;
const label = $('Setup Weekly').first().json.period === s.period && s.period === 'week' ? 'Weekly' : ($('Setup Daily').first().json.period === s.period ? 'Daily' : 'Weekly');
const bdt = (v) => `৳${Number(v || 0).toLocaleString()}`;
const top = (s.topProducts || []).map((p, i) => `${i + 1}. ${p.name} — ${p.unitsSold} units — ${bdt(p.revenue)}`).join('\n');
const text = [
  `<b>📊 ${label} Sales Digest</b>`,
  ``,
  `🧾 Orders: <b>${s.summary.orders}</b>`,
  `💰 Revenue: <b>${bdt(s.summary.revenue)}</b>`,
  `📈 AOV: ${bdt(s.summary.aov)}`,,
  `🏢 B2B orders: ${s.summary.b2bOrders} • COD: ${s.summary.codOrders}`,,
  `❌ Cancelled: ${s.cancelled}`,,
  ``,
  `<b>Top products:</b>\n${top || '—'}`
].join('\n');
const html = `
  <h2>📊 ${label} Sales Digest</h2>
  <table cellpadding="8" style="border-collapse:collapse">
    <tr><td>Orders</td><td><b>${s.summary.orders}</b></td></tr>
    <tr><td>Revenue</td><td><b>${bdt(s.summary.revenue)}</b></td></tr>
    <tr><td>Average order value</td><td>${bdt(s.summary.aov)}</td></tr>
    <tr><td>B2B orders</td><td>${s.summary.b2bOrders}</td></tr>
    <tr><td>COD orders</td><td>${s.summary.codOrders}</td></tr>
    <tr><td>Cancelled</td><td>${s.cancelled}</td></tr>
  </table>
  <h3>Top products</h3>
  <ol>${(s.topProducts || []).map((p) => `<li>${p.name} — ${p.unitsSold} units — ${bdt(p.revenue)}</li>`).join('')}</ol>`;
return { json: { CONFIG: cfg, text, html, label } };
